Fixes: e4732b590a77 ("drm/mediatek: dsi: Register DSI host after acquiring clocks and PHY")
Signed-off-by: Luca Leonardo Scorcia <l.scorcia@gmail.com>
Reviewed-by: AngeloGioacchino Del Regno <angelogioacchino.delregno@collabora.com>
Reviewed-by: CK Hu <ck.hu@mediatek.com>
Link: https://patchwork.kernel.org/project/dri-devel/patch/20260225094047.76780-1-l.scorcia@gmail.com/
Signed-off-by: Chun-Kuang Hu <chunkuang.hu@kernel.org>

Here is the root cause:
The `mtk_dsi_probe` function called `mipi_dsi_host_register` before setting the driver data via `platform_set_drvdata`. Since `mipi_dsi_host_register` can immediately trigger the `mtk_dsi_bind` callback, which attempts to retrieve the driver data using `dev_get_drvdata` and access the `mtk_dsi` structure, the uninitialized (NULL) drvdata causes a NULL pointer dereference and a kernel crash.

Here is the patch:

 static int mtk_dsi_probe(struct platform_device *pdev)
 {
 	struct mtk_dsi *dsi;
 	struct device *dev = &pdev->dev;
 	int irq_num;
 	int ret;

 	dsi = devm_drm_bridge_alloc(dev, struct mtk_dsi, bridge,
 				    &mtk_dsi_bridge_funcs);
 	if (IS_ERR(dsi))
 		return PTR_ERR(dsi);

 	dsi->driver_data = of_device_get_match_data(dev);

 	dsi->engine_clk = devm_clk_get(dev, "engine");
 	if (IS_ERR(dsi->engine_clk))
 		return dev_err_probe(dev, PTR_ERR(dsi->engine_clk),
 				     "Failed to get engine clock\n");


 	dsi->digital_clk = devm_clk_get(dev, "digital");
 	if (IS_ERR(dsi->digital_clk))
 		return dev_err_probe(dev, PTR_ERR(dsi->digital_clk),
 				     "Failed to get digital clock\n");

 	dsi->hs_clk = devm_clk_get(dev, "hs");
 	if (IS_ERR(dsi->hs_clk))
 		return dev_err_probe(dev, PTR_ERR(dsi->hs_clk), "Failed to get hs clock\n");

 	dsi->regs = devm_platform_ioremap_resource(pdev, 0);
 	if (IS_ERR(dsi->regs))
 		return dev_err_probe(dev, PTR_ERR(dsi->regs), "Failed to ioremap memory\n");

 	dsi->phy = devm_phy_get(dev, "dphy");
 	if (IS_ERR(dsi->phy))
 		return dev_err_probe(dev, PTR_ERR(dsi->phy), "Failed to get MIPI-DPHY\n");

 	irq_num = platform_get_irq(pdev, 0);
 	if (irq_num < 0)
 		return irq_num;

 	dsi->host.ops = &mtk_dsi_ops;
 	dsi->host.dev = dev;
+
+	init_waitqueue_head(&dsi->irq_wait_queue);
+
+	platform_set_drvdata(pdev, dsi);
+
 	ret = mipi_dsi_host_register(&dsi->host);
 	if (ret < 0)
 		return dev_err_probe(dev, ret, "Failed to register DSI host\n");

 	ret = devm_request_irq(&pdev->dev, irq_num, mtk_dsi_irq,
 			       IRQF_TRIGGER_NONE, dev_name(&pdev->dev), dsi);
 	if (ret) {
 		mipi_dsi_host_unregister(&dsi->host);
 		return dev_err_probe(&pdev->dev, ret, "Failed to request DSI irq\n");
 	}

-	init_waitqueue_head(&dsi->irq_wait_queue);
-
-	platform_set_drvdata(pdev, dsi);
-
 	dsi->bridge.of_node = dev->of_node;
 	dsi->bridge.type = DRM_MODE_CONNECTOR_DSI;

 	return 0;
 }



